CREATE TABLE orders (
    order_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer    text NOT NULL,
    amount      numeric(10,2) NOT NULL,
    ordered_at  timestamptz NOT NULL DEFAULT now()
);

INSERT INTO orders (customer, amount)
SELECT 'customer_' || g, round((random() * 5000)::numeric, 2)
  FROM generate_series(1, 100000) AS g;

SELECT oid, relname, relfilenode
  FROM pg_class
 WHERE relname IN ('orders', 'orders_pkey');

SELECT pg_relation_filepath('orders')      AS table_file,
       pg_relation_filepath('orders_pkey') AS index_file;

CREATE TABLE payments (payment_id int, amount numeric(10,2));
INSERT INTO payments VALUES (1, 250.00), (2, 990.50);

SELECT oid, relfilenode, pg_relation_filepath('payments')
  FROM pg_class WHERE relname = 'payments';

TRUNCATE payments;

SELECT oid, relfilenode, pg_relation_filepath('payments')
  FROM pg_class WHERE relname = 'payments';

SET log_temp_files = 0;
SET work_mem = '64kB';

SELECT count(*)
  FROM (SELECT customer FROM orders ORDER BY customer OFFSET 0) AS sorted;

SELECT datname, pg_size_pretty(pg_database_size(datname)) AS size
  FROM pg_database
 ORDER BY pg_database_size(datname) DESC;
